//! Golden-image comparison shared by the render and client integration tests.
//!
//! A golden image is a PNG generated by Tessera's own renderer from a synthetic scene and
//! committed next to the test (never game data). [`check`] compares a fresh render against
//! it with a per-channel tolerance, because GPU drivers (hardware vs. llvmpipe/lavapipe)
//! may differ by a rounding step in filtering and blending. Line rasterisation is
//! implementation-defined in Vulkan and GL (a 1-px line may land one pixel over), so a
//! pixel only counts as an outlier when no pixel within [`Tolerance::neighbourhood`] of it
//! in the other image matches either (checked both ways, so a missing line still fails).
//! A small budget of outliers is allowed on top.
//!
//! - `TESSERA_BLESS=1` (re)writes the golden image from the current render and passes.
//! - On a mismatch the actual image, the expected image and a diff image are written to
//!   `target/tmp/golden/` and the test fails with their paths. The same files are written
//!   (and the test passes) when the match is within tolerance but not exact.
//!
//! The diff image shows the expected image dimmed to grey, outliers in red (brightness =
//! size of the largest channel difference) and mismatches forgiven by the neighbourhood
//! search in yellow.
//!
//! Included with `#[path]` by more than one test crate, so unused items are allowed.
#![allow(dead_code)]

use std::fs::File;
use std::io::{BufReader, BufWriter};
use std::path::{Path, PathBuf};

use tessera_render::RgbaImage;

/// Environment variable that regenerates golden images instead of comparing.
pub const ENV_BLESS: &str = "TESSERA_BLESS";

/// How close a render must be to its golden image.
#[derive(Debug, Clone, Copy)]
pub struct Tolerance {
    /// Largest allowed absolute difference per 8-bit channel.
    pub per_channel: u8,
    /// Search radius in pixels for a matching pixel in the other image (0 = exact
    /// position only).
    pub neighbourhood: u32,
    /// Fraction of pixels (0..=1) allowed to be outliers.
    pub max_outlier_fraction: f64,
}

impl Default for Tolerance {
    fn default() -> Self {
        Self {
            per_channel: 4,
            neighbourhood: 1,
            max_outlier_fraction: 0.0025,
        }
    }
}

/// Result of comparing two equally sized RGBA8 buffers.
#[derive(Debug, Clone, PartialEq)]
pub struct Comparison {
    /// Pixels with no match within the tolerance (see [`Tolerance`]).
    pub outliers: usize,
    /// Pixels whose same-position counterpart differs by more than `per_channel`
    /// (outliers plus pixels forgiven by the neighbourhood search).
    pub strict_mismatches: usize,
    /// Total pixels compared.
    pub pixels: usize,
    /// Largest channel difference seen anywhere.
    pub max_diff: u8,
    /// First outlier `(x, y, expected, actual)`, for the failure message.
    pub first_outlier: Option<(u32, u32, [u8; 4], [u8; 4])>,
}

impl Comparison {
    /// Whether the comparison is within `tol`.
    #[must_use]
    pub fn passes(&self, tol: Tolerance) -> bool {
        let budget = (self.pixels as f64 * tol.max_outlier_fraction).floor() as usize;
        self.outliers <= budget
    }
}

/// Largest absolute channel difference between two RGBA8 pixels.
fn channel_diff(a: &[u8], b: &[u8]) -> u8 {
    a.iter()
        .zip(b)
        .map(|(x, y)| x.abs_diff(*y))
        .max()
        .unwrap_or(0)
}

/// Whether `px` is within `per_channel` of any pixel of `img` within `radius` of (x, y).
fn matches_near(img: &RgbaImage, x: u32, y: u32, px: &[u8], per_channel: u8, radius: u32) -> bool {
    let (x0, x1) = (x.saturating_sub(radius), (x + radius).min(img.width - 1));
    let (y0, y1) = (y.saturating_sub(radius), (y + radius).min(img.height - 1));
    (y0..=y1).any(|ny| {
        (x0..=x1).any(|nx| {
            let i = ((ny as usize) * (img.width as usize) + nx as usize) * 4;
            img.data
                .get(i..i + 4)
                .is_some_and(|q| channel_diff(q, px) <= per_channel)
        })
    })
}

/// Compare `actual` against `expected` (same size, RGBA8). Returns the statistics and a
/// diff image.
///
/// # Panics
///
/// When the sizes differ or a buffer is not `width * height * 4` bytes.
#[must_use]
pub fn compare(
    expected: &RgbaImage,
    actual: &RgbaImage,
    tol: Tolerance,
) -> (Comparison, RgbaImage) {
    assert_eq!(
        (expected.width, expected.height),
        (actual.width, actual.height),
        "compare() needs equal sizes"
    );
    let pixels = (expected.width as usize) * (expected.height as usize);
    assert!(
        expected.data.len() == pixels * 4 && actual.data.len() == pixels * 4,
        "compare() needs tightly packed RGBA8 buffers"
    );
    let mut diff = Vec::with_capacity(expected.data.len());
    let mut cmp = Comparison {
        outliers: 0,
        strict_mismatches: 0,
        pixels,
        max_diff: 0,
        first_outlier: None,
    };
    let width = expected.width.max(1);
    for (i, (e, a)) in expected
        .data
        .chunks_exact(4)
        .zip(actual.data.chunks_exact(4))
        .enumerate()
    {
        let (x, y) = (i as u32 % width, i as u32 / width);
        let d = channel_diff(e, a);
        cmp.max_diff = cmp.max_diff.max(d);
        let outlier = d > tol.per_channel
            && !(matches_near(expected, x, y, a, tol.per_channel, tol.neighbourhood)
                && matches_near(actual, x, y, e, tol.per_channel, tol.neighbourhood));
        if d > tol.per_channel {
            cmp.strict_mismatches += 1;
        }
        if outlier {
            cmp.outliers += 1;
            if cmp.first_outlier.is_none() {
                cmp.first_outlier =
                    Some((x, y, [e[0], e[1], e[2], e[3]], [a[0], a[1], a[2], a[3]]));
            }
            diff.extend_from_slice(&[128u8.saturating_add(d / 2), 0, 0, 255]);
        } else if d > tol.per_channel {
            // Forgiven by the neighbourhood search: yellow.
            diff.extend_from_slice(&[160, 140, 0, 255]);
        } else {
            // Rec. 601 luma of the expected pixel, dimmed so red stands out.
            let luma =
                (u32::from(e[0]) * 299 + u32::from(e[1]) * 587 + u32::from(e[2]) * 114) / 1000;
            let g = (luma / 3) as u8;
            diff.extend_from_slice(&[g, g, g, 255]);
        }
    }
    let diff = RgbaImage {
        width: expected.width,
        height: expected.height,
        data: diff,
    };
    (cmp, diff)
}

/// Write an RGBA8 image as PNG.
pub fn write_png(path: &Path, img: &RgbaImage) -> std::io::Result<()> {
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let mut enc = png::Encoder::new(BufWriter::new(File::create(path)?), img.width, img.height);
    enc.set_color(png::ColorType::Rgba);
    enc.set_depth(png::BitDepth::Eight);
    enc.set_compression(png::Compression::High);
    let mut w = enc.write_header().map_err(std::io::Error::other)?;
    w.write_image_data(&img.data)
        .map_err(std::io::Error::other)?;
    w.finish().map_err(std::io::Error::other)
}

/// Read a PNG written by [`write_png`] (8-bit RGBA only).
pub fn read_png(path: &Path) -> std::io::Result<RgbaImage> {
    let dec = png::Decoder::new(BufReader::new(File::open(path)?));
    let mut reader = dec.read_info().map_err(std::io::Error::other)?;
    let size = reader
        .output_buffer_size()
        .ok_or_else(|| std::io::Error::other("PNG too large"))?;
    let mut data = vec![0u8; size];
    let info = reader
        .next_frame(&mut data)
        .map_err(std::io::Error::other)?;
    if info.color_type != png::ColorType::Rgba || info.bit_depth != png::BitDepth::Eight {
        return Err(std::io::Error::other(format!(
            "{}: expected 8-bit RGBA, got {:?} {:?}",
            path.display(),
            info.color_type,
            info.bit_depth
        )));
    }
    data.truncate(info.buffer_size());
    Ok(RgbaImage {
        width: info.width,
        height: info.height,
        data,
    })
}

/// Whether `TESSERA_BLESS` asks for golden images to be regenerated.
#[must_use]
pub fn blessing() -> bool {
    std::env::var(ENV_BLESS).is_ok_and(|v| !v.is_empty() && v != "0")
}

/// Directory that receives actual/expected/diff images of failed comparisons.
#[must_use]
pub fn artifact_dir() -> PathBuf {
    Path::new(env!("CARGO_TARGET_TMPDIR")).join("golden")
}

/// Compare `actual` against the golden PNG at `golden`, or rewrite it when blessing.
///
/// # Panics
///
/// On a mismatch, a size change, or a missing golden image (when not blessing); the
/// message names the artifact files and the bless command.
pub fn check(golden: &Path, actual: &RgbaImage, tol: Tolerance) {
    let name = golden
        .file_stem()
        .map_or_else(|| "golden".to_owned(), |s| s.to_string_lossy().into_owned());
    if blessing() {
        write_png(golden, actual).expect("writing golden image");
        eprintln!("blessed {}", golden.display());
        return;
    }
    let hint = format!("rerun with {ENV_BLESS}=1 to regenerate it if the change is intended");
    let expected = match read_png(golden) {
        Ok(img) => img,
        Err(e) => {
            let out = artifact_dir().join(format!("{name}.actual.png"));
            let _ = write_png(&out, actual);
            panic!(
                "cannot read golden image {}: {e}\n  actual render: {}\n  {hint}",
                golden.display(),
                out.display()
            );
        }
    };
    let dir = artifact_dir();
    let actual_path = dir.join(format!("{name}.actual.png"));
    if (expected.width, expected.height) != (actual.width, actual.height) {
        let _ = write_png(&actual_path, actual);
        panic!(
            "{}: size {}x{} differs from render {}x{}\n  actual render: {}\n  {hint}",
            golden.display(),
            expected.width,
            expected.height,
            actual.width,
            actual.height,
            actual_path.display()
        );
    }
    let (cmp, diff) = compare(&expected, actual, tol);
    eprintln!(
        "golden {name}: {} outliers of {} pixels (budget {:.2} %), {} beyond ±{} at the \
         same position, max channel diff {}",
        cmp.outliers,
        cmp.pixels,
        tol.max_outlier_fraction * 100.0,
        cmp.strict_mismatches,
        tol.per_channel,
        cmp.max_diff
    );
    let expected_path = dir.join(format!("{name}.expected.png"));
    let diff_path = dir.join(format!("{name}.diff.png"));
    // Any inexact match leaves the images behind, so driver differences that are still
    // within tolerance can be inspected (and uploaded by CI).
    if cmp.strict_mismatches > 0 {
        let _ = write_png(&actual_path, actual);
        let _ = write_png(&expected_path, &expected);
        let _ = write_png(&diff_path, &diff);
        eprintln!("  inexact match; images in {}", dir.display());
    }
    if cmp.passes(tol) {
        return;
    }
    panic!(
        "{} does not match: {} of {} pixels differ by more than {} per channel with no \
         match within {} px (allowed {}), max diff {}, first at {:?}\n  actual:   {}\n  expected: {}\n  diff:     {}\n  {hint}",
        golden.display(),
        cmp.outliers,
        cmp.pixels,
        tol.per_channel,
        tol.neighbourhood,
        (cmp.pixels as f64 * tol.max_outlier_fraction).floor() as usize,
        cmp.max_diff,
        cmp.first_outlier,
        actual_path.display(),
        expected_path.display(),
        diff_path.display(),
    );
}
